        metrics = exp.get('metrics', {})
        spatial_postfix[exp_id] = {
            'status': exp.get('status'),
            'conclusion': exp.get('conclusion'),
            'overall_sr': metrics.get('overall_sr') if metrics else None
        }

for k, v in sorted(spatial_postfix.items()):
    print(f'{k}: {v}')
